extends Node

signal action_rebound(action: StringName, event: InputEvent)

var _default_bindings: Dictionary = {}

func _ready() -> void:
	_capture_defaults()

func _capture_defaults() -> void:
	for action in InputMap.get_actions():
		if action.begins_with("ui_"):
			continue
		_default_bindings[action] = InputMap.action_get_events(action).duplicate()

func reset_to_defaults() -> void:
	for action in InputMap.get_actions():
		if action.begins_with("ui_"):
			continue
		InputMap.action_erase_events(action)
		if action in _default_bindings:
			for event in _default_bindings[action]:
				InputMap.action_add_event(action, event)
			# Remove keycode/button_index from memory to be safe? Not strictly needed,
			# but calling rebind_action with default would add events fresh.

func rebind_action(action: StringName, new_event: InputEvent) -> void:
	InputMap.action_erase_events(action)
	if new_event != null:
		InputMap.action_add_event(action, new_event)
	emit_signal("action_rebound", action, new_event)

func get_action_event(action: StringName) -> InputEvent:
	var events = InputMap.action_get_events(action)
	return events[0] if events.size() > 0 else null

func save_to_file(path: String = "user://input_map.cfg") -> void:
	var config = ConfigFile.new()
	for action in InputMap.get_actions():
		if action.begins_with("ui_"):
			continue
		var events = InputMap.action_get_events(action)
		var serialized = []
		for event in events:
			if event is InputEventKey:
				serialized.append({"keycode": event.keycode})
			elif event is InputEventJoypadButton:
				serialized.append({"button_index": event.button_index})
		config.set_value("bindings", action, serialized)
	config.save(path)

func load_from_file(path: String = "user://input_map.cfg") -> bool:
	if not FileAccess.file_exists(path):
		return false
	var config = ConfigFile.new()
	var err = config.load(path)
	if err != OK:
		return false
	if not config.has_section("bindings"):
		return true
	for action in config.get_section_keys("bindings"):
		var serialized = config.get_value("bindings", action)
		InputMap.action_erase_events(action)
		for item in serialized:
			if item is Dictionary:
				var event: InputEvent = null
				if item.has("keycode"):
					event = InputEventKey.new()
					event.keycode = item["keycode"]
				elif item.has("button_index"):
					event = InputEventJoypadButton.new()
					event.button_index = item["button_index"]
				if event != null:
					InputMap.action_add_event(action, event)
	return true
EOF
echo done

cd /home/user/input_remap && mkdir -p scenes && cat > scenes/RemapButton.gd <<'EOF'
extends Button

@export var action_name: StringName

var _is_listening: bool = false

func _ready() -> void:
	pressed.connect(_on_pressed)
	_update_label()
	InputRemapper.action_rebound.connect(_on_action_rebound)

func _update_label() -> void:
	var event = InputRemapper.get_action_event(action_name)
	if event != null:
		text = event.as_text()
	else:
		text = "Unbound"

func _on_pressed() -> void:
	_is_listening = true
	text = "Listening..."

func _on_action_rebound(action: StringName, event: InputEvent) -> void:
	if action == action_name:
		_update_label()

func _unhandled_input(event: InputEvent) -> void:
	if not _is_listening:
		return
	if event is InputEventKey or event is InputEventJoypadButton:
		if event.is_pressed():
			accept_event()
			_is_listening = false
			InputRemapper.rebind_action(action_name, event)
EOF
